// reviewsource: wire and length are caller-controlled; wire has length readable bytes.
void decode(const char *wire, size_t length) {
  char out[24];
  memcpy(out, wire, length);
  consume(out);
}

// reviewsource: wire has length readable bytes; no later string operations occur.
void decode(const char *wire, size_t length) {
  char out[24];
  if (length > sizeof(out)) return;
  memcpy(out, wire, length);
}
